   9 async function getInitialProject(id: string) {
  10   if (!id) return null;
  11   
  12   try {
  13     const controller = container.resolve(ProjectController);
  14     const result = await controller.getProjectById(id);
  15     
  16     if (result.isSuccess) {
  17       return result.getValue().toProperties();
  18     }
  19   } catch (error) {
  20     console.error('Failed to fetch initial project on server:', error);
  21   }
  22   return null;
  23 }
  24 
  25 export default async function GeneratePage(props: { searchParams: Promise<{ id?: string }> }) {
  26   const searchParams = await props.searchParams;
  27   const projectId = searchParams.id;
  28 
  29   const initialProject = projectId ? await getInitialProject(projectId) : null;
  30 
  31   return (
  32     <Suspense fallback={<BuilderPageSkeleton />}>
  33       <ReportModeGenerator initialProject={initialProject} />
  34     </Suspense>
  35   );
  36 }
