'use client';

import React from 'react';
import { CollapsibleSidePanel } from '@/components/ui/CollapsibleSidePanel';
import { cn } from '@/infrastructure/utils/cn';
import { BuilderSidebarProps } from './types';

export const BuilderSidebar = React.forwardRef<HTMLDivElement, BuilderSidebarProps>((
    {
        panels,
        activeKey,
        onActiveKeyChange,
        side,
        className,
    },
    ref
) => {
    const isCollapsed = !activeKey;

    return (
        <div
            ref={ref}
            className={cn(
                'flex flex-col h-full bg-background/40 backdrop-blur-2xl transition-all duration-500 ease-[0.22,1,0.36,1] relative overflow-hidden z-20',
                'border border-primary/10 shadow-[0_8px_40px_rgba(0,0,0,0.08)] rounded-[32px]',
                isCollapsed ? 'w-[72px]' : 'w-[400px]',
                className
            )}
        >
            {/* Dot-grid atmosphere — aligned with BuilderCanvas & BuilderHeader (28px, 1.5px center) */}
            <div
                className="absolute inset-0 opacity-[0.02] dark:opacity-[0.04] pointer-events-none"
                style={{
                    backgroundImage: 'radial-gradient(circle at 1.5px 1.5px, hsl(var(--primary)) 1px, transparent 0)',
                    backgroundSize: '28px 28px',
                }}
            />

            <div className="h-full w-full min-w-0 flex flex-col relative z-10">
                <CollapsibleSidePanel
                    panels={panels}
                    activeKey={activeKey}
                    onActiveKeyChange={onActiveKeyChange}
                    side={side}
                    className="rounded-none border-none bg-transparent shadow-none h-full"
                />
            </div>
        </div>
    );
});

BuilderSidebar.displayName = 'BuilderSidebar';

'use client';

import React, { Suspense } from 'react';
import { BuilderPageSkeleton } from '@/app/builder/loading';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Button } from '@/components/ui/button';
import { ZoomIn, ZoomOut, RotateCcw } from 'lucide-react';
import { cn } from '@/infrastructure/utils/cn';

interface BuilderCanvasProps {
    children: React.ReactNode;
    zoomLevel: number;
    onZoomIn: () => void;
    onZoomOut: () => void;
    onZoomReset: () => void;
    floatingElements?: React.ReactNode;
    className?: string;
}

export const BuilderCanvas = React.forwardRef<HTMLDivElement, BuilderCanvasProps>((
    {
        children,
        zoomLevel,
        onZoomIn,
        onZoomOut,
        onZoomReset,
        floatingElements,
        className,
    },
    ref
) => {
    return (
        <div
            ref={ref}
            className={cn(
                "flex flex-col h-full w-full bg-muted/5 relative overflow-hidden transition-all duration-700 ease-[0.22,1,0.36,1] z-10",
                className
            )}
        >
            {/* Subtle dot-grid atmosphere */}
            <div
                className="absolute inset-0 opacity-[0.03] dark:opacity-[0.05] pointer-events-none"
                style={{
                    backgroundImage: 'radial-gradient(circle at 1.5px 1.5px, hsl(var(--primary)) 1px, transparent 0)',
                    backgroundSize: '28px 28px',
                }}
            />

            {/* Top ambient gradient — frames the top edge softly */}
            <div className="absolute inset-x-0 top-0 h-20 bg-gradient-to-b from-background/50 to-transparent pointer-events-none z-10" />

            {/* Bottom ambient gradient — softens the lower edge */}
            <div className="absolute inset-x-0 bottom-0 h-20 bg-gradient-to-t from-background/15 to-transparent pointer-events-none z-10" />

            {/* Inner vignette ring — frames the canvas like a viewport */}
            <div
                className="absolute inset-0 pointer-events-none z-10 rounded-[inherit]"
                style={{ boxShadow: 'inset 0 0 60px 0 hsl(var(--background) / 0.25)' }}
            />

            {/* Primary content area */}
            <main className="flex-1 flex flex-col min-h-0 overflow-hidden relative z-20">
                <Suspense fallback={<BuilderPageSkeleton />}>
                    <div className="flex-1 overflow-auto custom-scrollbar transition-all duration-700 ease-[0.22,1,0.36,1]">
                        {children}
                    </div>
                </Suspense>
            </main>

            {/* Floating contextual layers (e.g. FloatingOutline) */}
            {floatingElements}

            {/* Zoom HUD — always visible at reduced opacity, brightens on hover */}
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-40 transition-all duration-300 opacity-50 hover:opacity-100 focus-within:opacity-100">
                <TooltipProvider delayDuration={200}>
                    <div
                        className="flex items-center gap-0.5 px-1.5 py-1.5 bg-background/70 backdrop-blur-2xl border border-border/30 rounded-full shadow-[0_4px_24px_rgba(0,0,0,0.10)] ring-1 ring-white/[0.06]"
                        role="toolbar"
                        aria-label="Zoom controls"
                    >
                        {/* Zoom Out */}
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    aria-label="Zoom out"
                                    className="h-8 w-8 rounded-full hover:bg-primary/10 hover:text-primary transition-all active:scale-90"
                                    onClick={onZoomOut}
                                >
                                    <ZoomOut className="h-3.5 w-3.5" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent
                                side="top"
                                className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mb-2"
                            >
                                Zoom Out <span className="opacity-50 ml-1 font-normal normal-case tracking-normal">Ctrl −</span>
                            </TooltipContent>
                        </Tooltip>

                        {/* Zoom percentage — click to reset */}
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <button
                                    onClick={onZoomReset}
                                    aria-label={`Current zoom: ${Math.round(zoomLevel * 100)}%. Click to reset.`}
                                    className="px-3.5 min-w-[3.75rem] text-center select-none border-x border-primary/10 mx-0.5 cursor-pointer rounded-sm hover:bg-primary/5 transition-colors focus:outline-none focus-visible:ring-1 focus-visible:ring-primary/40"
                                >
                                    <span className="text-[10px] font-black tracking-[0.25em] text-foreground/75 tabular-nums">
                                        {Math.round(zoomLevel * 100)}%
                                    </span>
                                </button>
                            </TooltipTrigger>
                            <TooltipContent
                                side="top"
                                className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mb-2"
                            >
                                Reset Zoom <span className="opacity-50 ml-1 font-normal normal-case tracking-normal">Ctrl 0</span>
                            </TooltipContent>
                        </Tooltip>

                        {/* Zoom In */}
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    aria-label="Zoom in"
                                    className="h-8 w-8 rounded-full hover:bg-primary/10 hover:text-primary transition-all active:scale-90"
                                    onClick={onZoomIn}
                                >
                                    <ZoomIn className="h-3.5 w-3.5" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent
                                side="top"
                                className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mb-2"
                            >
                                Zoom In <span className="opacity-50 ml-1 font-normal normal-case tracking-normal">Ctrl +</span>
                            </TooltipContent>
                        </Tooltip>

                        {/* Divider */}
                        <div className="w-px h-4 bg-border/40 mx-1" aria-hidden />

                        {/* Reset button (explicit icon) */}
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    aria-label="Reset zoom to 100%"
                                    className="h-8 w-8 rounded-full hover:bg-primary/10 hover:text-primary transition-all active:rotate-180 duration-500"
                                    onClick={onZoomReset}
                                >
                                    <RotateCcw className="h-3 w-3" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent
                                side="top"
                                className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mb-2"
                            >
                                Reset to 100%
                            </TooltipContent>
                        </Tooltip>
                    </div>
                </TooltipProvider>
            </div>
        </div>
    );
});

BuilderCanvas.displayName = 'BuilderCanvas';

'use client';

import React, { useRef } from 'react';
import { BookOpenText, PlusCircle, Upload, Download, Loader2, Save } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { cn } from '@/infrastructure/utils/cn';
import { useLocalization } from '@/context/LocalizationContext';
import { useBuilderStore } from '@/hooks';
import { useProjectFileOperations } from '@/modules/projects/adapters/hooks/useProjectFileOperations';
import { BrowseProjectsDialog } from '../session/BrowseProjectsDialog';
import { ExportDialog } from '../session/ExportDialog';

interface BuilderHeaderProps {
    projectName: string;
    onProjectNameChange: (name: string) => void;
    onProjectNameBlur: () => void;
    isSaving: boolean;
    hasUnsavedChanges: boolean;
    onSave: () => void;
    className?: string;
}

export const BuilderHeader = React.forwardRef<HTMLDivElement, BuilderHeaderProps>(({
    projectName,
    onProjectNameChange,
    onProjectNameBlur,
    isSaving,
    hasUnsavedChanges,
    onSave,
    className,
}, ref) => {
    const { t } = useLocalization();
    const { project, newSession } = useBuilderStore();
    const { handleUploadProject, handleDownloadProject } = useProjectFileOperations();
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleUploadClick = () => {
        fileInputRef.current?.click();
    };

    const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            try {
                await handleUploadProject(file);
            } catch (error) {
                // Error already handled in the hook
            }
        }
        if (e.target) e.target.value = '';
    };

    const handleDownload = () => {
        if (project) {
            handleDownloadProject(project);
        }
    };

    const hasContent = project?.hasContent() ?? false;

    return (
        <header
            ref={ref}
            className={cn(
                "h-16 flex items-center justify-between gap-8 px-6 bg-background/40 backdrop-blur-3xl border border-primary/10 shadow-2xl rounded-[32px] transition-all duration-700 ease-[0.22,1,0.36,1] relative overflow-hidden pointer-events-auto",
                className
            )}
        >
            {/* Dot-grid atmosphere — aligned with BuilderCanvas (28px, 1.5px center) */}
            <div
                className="absolute inset-0 opacity-[0.02] dark:opacity-[0.04] pointer-events-none"
                style={{
                    backgroundImage: 'radial-gradient(circle at 1.5px 1.5px, hsl(var(--primary)) 1px, transparent 0)',
                    backgroundSize: '28px 28px',
                }}
            />

            {/* Inner highlights for premium glass feel */}
            <div className="absolute inset-0 pointer-events-none ring-1 ring-inset ring-white/10 dark:ring-white/5 rounded-[inherit]" />

            {/* Left — brand + project identity */}
            <div className="flex items-center gap-4 relative z-10 min-w-0">
                {/* Logo HUD */}
                <div className="h-9 w-9 bg-primary/10 rounded-xl flex items-center justify-center border border-primary/20 shadow-[inset_0_0_12px_rgba(var(--primary),0.1)] group/logo overflow-hidden relative transition-all duration-500 hover:border-primary/30 shrink-0">
                    <div className="absolute inset-0 bg-gradient-to-br from-primary/10 to-transparent opacity-0 group-hover/logo:opacity-100 transition-opacity duration-500" />
                    <BookOpenText className="h-4.5 w-4.5 text-primary relative z-10 transition-transform duration-500 group-hover/logo:scale-110" />
                </div>

                {/* Project name + metadata */}
                <div className="flex flex-col gap-0.5 min-w-0">
                    <div className="relative group/input">
                        <Input
                            className="h-7 px-1 py-0 text-[13px] font-black uppercase tracking-[0.05em] bg-transparent border-none focus-visible:ring-0 focus-visible:ring-offset-0 min-w-[200px] max-w-[320px] text-foreground/90 truncate transition-all duration-300"
                            value={projectName}
                            onChange={(e) => onProjectNameChange(e.target.value)}
                            onBlur={onProjectNameBlur}
                            placeholder="Untitled Project"
                        />
                        {/* Animated underline on hover/focus */}
                        <div className="absolute -bottom-0.5 left-0 w-0 h-[1px] bg-primary/60 group-hover/input:w-full transition-all duration-500" />
                    </div>

                    <div className="flex items-center gap-2.5 px-1">
                        <Badge
                            variant="outline"
                            className="text-[8px] font-black uppercase tracking-[0.22em] py-0 h-3.5 border-primary/20 bg-primary/5 text-primary/70 px-1.5"
                        >
                            v2.4
                        </Badge>
                        <div className="flex items-center gap-1 opacity-40">
                            <div className="h-1 w-1 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.4)]" />
                            <span className="text-[8px] font-black uppercase tracking-[0.18em] text-muted-foreground">Active Hub</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Right — session actions */}
            <div className="flex items-center gap-3 relative z-10 shrink-0">
                <TooltipProvider delayDuration={200}>
                    {/* Action pill — a nested floating-style container */}
                    <div className="flex items-center gap-1 bg-background/20 backdrop-blur-md p-1 rounded-2xl border border-white/10 shadow-inner shadow-black/5 dark:shadow-white/5 transition-all duration-500 hover:border-primary/15">
                        <input
                            type="file"
                            ref={fileInputRef}
                            onChange={onFileChange}
                            accept=".arkan"
                            className="hidden"
                        />

                        {/* File ops group */}
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={() => newSession()}
                                    className="h-8 w-8 xl:w-auto xl:px-3 gap-1.5 text-[9px] font-black uppercase tracking-[0.18em] hover:bg-primary/10 hover:text-primary transition-all duration-200 rounded-xl text-muted-foreground"
                                >
                                    <PlusCircle className="h-4 w-4 shrink-0" />
                                    <span className="hidden xl:inline">New</span>
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-3">
                                New Project
                            </TooltipContent>
                        </Tooltip>

                        <BrowseProjectsDialog />

                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={handleUploadClick}
                                    className="h-8 w-8 xl:w-auto xl:px-3 gap-1.5 text-[9px] font-black uppercase tracking-[0.18em] hover:bg-primary/10 hover:text-primary transition-all duration-200 rounded-xl text-muted-foreground"
                                >
                                    <Upload className="h-4 w-4 shrink-0" />
                                    <span className="hidden xl:inline">Import</span>
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-3">
                                Import .arkan File
                            </TooltipContent>
                        </Tooltip>

                        {/* Divider — tactical hairline */}
                        <div className="h-5 w-px bg-primary/10 mx-1" aria-hidden />

                        {/* Persistence group */}
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant={hasUnsavedChanges ? 'default' : 'ghost'}
                                    size="sm"
                                    onClick={onSave}
                                    disabled={!hasUnsavedChanges || isSaving}
                                    className={cn(
                                        "h-8 px-4 gap-2 text-[9px] font-black uppercase tracking-[0.22em] transition-all duration-500 rounded-xl",
                                        hasUnsavedChanges && !isSaving
                                            ? "shadow-[0_0_24px_rgba(var(--primary),0.3)] bg-primary hover:bg-primary/90 hover:scale-[1.03] active:scale-[0.98] ring-1 ring-inset ring-white/20"
                                            : "hover:bg-primary/10 hover:text-primary opacity-50 hover:opacity-100 text-muted-foreground"
                                    )}
                                >
                                    {isSaving ? (
                                        <Loader2 className="h-4 w-4 animate-spin shrink-0" />
                                    ) : (
                                        <div className="relative shrink-0">
                                            <Save className="h-4 w-4" />
                                            {hasUnsavedChanges && !isSaving && (
                                                <div className="absolute -top-1.5 -right-1.5 h-2 w-2 bg-white rounded-full animate-ping shadow-[0_0_8px_rgba(255,255,255,0.8)]" />
                                            )}
                                        </div>
                                    )}
                                    <span className="hidden xl:inline">Save Project</span>
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-3">
                                Save Progress
                                <span className="opacity-50 ml-1.5 font-normal normal-case tracking-normal">Ctrl S</span>
                            </TooltipContent>
                        </Tooltip>

                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={handleDownload}
                                    disabled={!hasContent}
                                    className="h-8 w-8 xl:w-auto xl:px-3 gap-1.5 text-[9px] font-black uppercase tracking-[0.18em] hover:bg-primary/10 hover:text-primary transition-all duration-200 rounded-xl text-muted-foreground disabled:opacity-30"
                                >
                                    <Download className="h-4 w-4 shrink-0" />
                                    <span className="hidden xl:inline">Export</span>
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-3">
                                Download as .arkan
                            </TooltipContent>
                        </Tooltip>

                        {/* Divider — tactical hairline */}
                        <div className="h-5 w-px bg-primary/10 mx-1" aria-hidden />

                        <ExportDialog />
                    </div>
                </TooltipProvider>
            </div>
        </header>
    );
});

BuilderHeader.displayName = 'BuilderHeader';

'use client';

import React from 'react';
import { cn } from '@/infrastructure/utils/cn';

interface BuilderLayoutProps {
    header: React.ReactNode;
    leftSidebar?: React.ReactNode;
    rightSidebar?: React.ReactNode;
    canvas: React.ReactNode;
    floatingElements?: React.ReactNode;
    className?: string;
}

export const BuilderLayout: React.FC<BuilderLayoutProps> = ({
    header,
    leftSidebar,
    rightSidebar,
    canvas,
    floatingElements,
    className,
}) => {
    return (
        <div className={cn("relative flex-grow flex flex-col bg-background h-[calc(100vh-64px)] overflow-hidden", className)}>
            <main className="flex-1 flex flex-col relative z-10 overflow-hidden">
                {/* Floating Global Header HUD */}
                {header && (
                    <div className="absolute top-6 left-1/2 -translate-x-1/2 z-50 w-auto max-w-[95vw] pointer-events-none">
                        {header}
                    </div>
                )}

                {/* Base Canvas Layer */}
                <div className="absolute inset-0 z-10">
                    {canvas}
                </div>

                {/* Floating Sidebar Controls */}
                <div className="absolute inset-0 z-30 pointer-events-none flex items-stretch justify-between p-6">
                    {/* Left Sidebar HUD */}
                    {leftSidebar && (
                        <div className="pointer-events-auto h-full flex flex-col">
                            {leftSidebar}
                        </div>
                    )}

                    {/* Right Sidebar HUD */}
                    {rightSidebar && (
                        <div className="pointer-events-auto h-full flex flex-col">
                            {rightSidebar}
                        </div>
                    )}
                </div>

                {/* Additional Global Floating Layers (Outline, Chat, etc.) */}
                {floatingElements}
            </main>
        </div>
    );
};

'use client';

import React from 'react';
import { cn } from '@/infrastructure/utils/cn';
import { BuilderCanvas } from '../layout/BuilderCanvas';
import ReportResults from '../../report-mode/ReportResults';
import { FloatingOutline } from '../../report-mode/FloatingOutline';

interface DocumentCanvasProps {
    zoomLevel: number;
    onZoomIn: () => void;
    onZoomOut: () => void;
    onZoomReset: () => void;
