export const BuilderWorkspace: React.FC<BuilderWorkspaceProps> = ({ initialProject }) => {
    const {
        project,
        updateProject,
        updateProjectName,
        isSaving,
        hasUnsavedChanges,
        handleSave,
        activeChapterId,
        setActiveChapterId,
        selectedSectionIds,
        handleActiveSectionChange,
        activePanelKey,
        setActivePanelKey,
        activeRightPanelKey,
        setActiveRightPanelKey,
        isOutlineVisible,
        setIsOutlineVisible,
        zoomLevel,
        handleZoomIn,
        handleZoomOut,
        handleZoomReset,
        handleMoveItem,
        handleUpdateTitle,
        handleDeleteItem,
        handleAddChapter,
        handleAddSection,
        handleDuplicateItem,
        handleUndo,
        handleCopyItem,
        handlePasteItem,
        summarizeMutation,
        expandMutation,
        rewriteMutation,
        rewriteStyles,
        viewMode,
        setViewMode,
    } = useReportGenerator(initialProject);

    const { leftPanels, rightPanels } = useSidebarPanels({
        project,
        activeChapterId,
        selectedSectionIds,
        onActiveChapterChange: setActiveChapterId,
        onActiveSectionChange: handleActiveSectionChange,
    });

    const [showOnboarding, setShowOnboarding] = useState(false);

    useEffect(() => {
        const completed = localStorage.getItem('arkan_onboarding_completed');
        if (!completed) {
            setShowOnboarding(true);
        }
    }, []);

    const handleOnboardingComplete = () => {
        localStorage.setItem('arkan_onboarding_completed', 'true');
