'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { cn } from '@/infrastructure/utils/cn';
import { GripVertical, ChevronRight, ChevronDown, Check, Pencil, Trash2 } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';

/**
 * SortableOutlineItem — A shared high-fidelity component for document structure nodes.
 * Used in both the ProjectOutlineHUD and SidebarOutlineManager.
 */

interface SortableOutlineItemProps {
  id: string;
  index: number;
  title: string;
  isActive: boolean;
  isChapter?: boolean;
  isExpanded?: boolean;
  hasContent?: boolean;
  onActivate: () => void;
  onToggleExpand?: () => void;
  onUpdateTitle?: (newTitle: string) => void;
  onDelete?: () => void;
  children?: React.ReactNode;
  className?: string;
}

export const SortableOutlineItem = ({
  id,
  index,
  title,
  isActive,
  isChapter,
  isExpanded,
  hasContent,
  onActivate,
  onToggleExpand,
  onUpdateTitle,
  onDelete,
  children,
  className,
}: SortableOutlineItemProps) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(title);

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id,
    disabled: isEditing,
  });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 50 : 'auto',
  };

  const handleStartEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsEditing(true);
    setEditValue(title);
  };

  const handleFinishEdit = () => {
    if (editValue.trim() && editValue !== title) {
      onUpdateTitle?.(editValue.trim());
    }
    setIsEditing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleFinishEdit();
    if (e.key === 'Escape') {
      setIsEditing(false);
      setEditValue(title);
    }
  };

  return (
    <div 
        ref={setNodeRef} 
        style={style} 
        className={cn(
            'group/item select-none transition-all duration-300', 
            isChapter ? 'mb-2' : 'mb-1 ml-4',
            className
        )}
    >
      <div
        className={cn(
          'flex items-center gap-2 p-1.5 rounded-xl transition-all duration-300 cursor-pointer border',
          isActive
            ? 'bg-primary/10 border-primary/20 shadow-[0_2px_8px_rgba(var(--primary),0.08)]'
            : 'bg-transparent border-transparent hover:bg-muted/10'
        )}
        onDoubleClick={handleStartEdit}
      >
        {/* Drag handle — Pulse icon on hover */}
        <div
          {...attributes}
          {...listeners}
          className="p-0.5 transition-all duration-300 opacity-0 group-hover/item:opacity-40 cursor-grab active:cursor-grabbing hover:opacity-100"
        >
          <GripVertical className="h-3.5 w-3.5" />
        </div>

        {/* Node Identity + Label */}
        <div
          className="flex-1 flex items-center gap-2.5 min-w-0"
          onClick={(e) => {
            e.stopPropagation();
            onActivate();
          }}
        >
          {isChapter && !isEditing && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onToggleExpand?.();
              }}
              className="p-1 hover:bg-primary/10 rounded-lg transition-all active:scale-90"
            >
              {isExpanded ? (
                <ChevronDown className="h-3.5 w-3.5" />
              ) : (
                <ChevronRight className="h-3.5 w-3.5 text-primary/40" />
              )}
            </button>
          )}

          {/* Status Dot — Architectural state indicator */}
          {!isEditing && (
            <div
              className={cn(
                'h-1.5 w-1.5 rounded-full shrink-0 transition-colors duration-500',
                hasContent ? 'bg-green-500 shadow-[0_0_6px_rgba(34,197,94,0.4)]' : 'bg-amber-500/40'
              )}
            />
          )}

          {/* Technical Index */}
          {!isEditing && (
            <span
              className={cn(
                'text-[9px] font-black tabular-nums opacity-40 uppercase tracking-[0.15em] shrink-0',
                isActive && 'opacity-100 text-primary'
              )}
            >
              {(index + 1).toString().padStart(2, '0')}
            </span>
          )}

          {/* Inline Content Title HUD */}
          {isEditing ? (
            <div className="flex-1 flex items-center gap-1.5">
              <Input
                autoFocus
                value={editValue}
                onChange={(e) => setEditValue(e.target.value)}
                onBlur={handleFinishEdit}
                onKeyDown={handleKeyDown}
                className="h-6 text-[10px] py-0 px-2 bg-background border-primary/20 rounded-lg font-bold uppercase tracking-widest focus-visible:ring-primary/20"
              />
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6 text-green-600 shrink-0"
                onClick={handleFinishEdit}
              >
                <Check className="h-3.5 w-3.5" />
              </Button>
            </div>
          ) : (
            <span
              className={cn(
                'text-[10px] font-bold uppercase tracking-widest truncate transition-colors duration-300',
                isActive ? 'text-primary' : 'text-muted-foreground group-hover/item:text-foreground',
                isChapter && 'font-black tracking-[0.18em]'
              )}
            >
              {title || (isChapter ? 'Untitled Chapter' : 'Untitled Section')}
            </span>
          )}
        </div>

        {/* Action Controls HUD — Segmented */}
        {!isEditing && (
          <div className="flex items-center gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity">
            <Button
              variant="ghost"
              size="icon"
              className="h-6 w-6 rounded-lg hover:bg-primary/10 text-muted-foreground hover:text-primary transition-all"
              onClick={handleStartEdit}
            >
              <Pencil className="h-2.5 w-2.5" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-6 w-6 rounded-lg hover:bg-red-500/10 text-muted-foreground hover:text-red-600 transition-all"
              onClick={(e) => {
                e.stopPropagation();
                onDelete?.();
              }}
            >
              <Trash2 className="h-2.5 w-2.5" />
            </Button>
          </div>
        )}
      </div>

      {/* Recursion / Nested Content Branch */}
      <AnimatePresence>
        {isChapter && isExpanded && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
            className="mt-1 border-l border-primary/10 ml-[13px] pl-1 overflow-hidden"
          >
            {children}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

'use client';

import { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { toast, useBuilderStore } from '@/hooks';
import { Chapter } from '@/modules/ai-content/domain/entities/Chapter';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { Project } from '@/modules/projects/domain/entities/Project';

/**
 * useOutlineOperations — Consolidated project mutation logic for the Outline system.
 * Handles structural changes, clipboard operations, and history integration.
 */

export const useOutlineOperations = (project: Project | null) => {
  const updateProject = useBuilderStore(state => state.updateProject);
  const undo = useBuilderStore(state => state.undo);
  const [clipboard, setClipboard] = useState<{ type: 'chapter' | 'section'; data: any } | null>(null);

  const handleMoveItem = (activeId: string, overId: string) => {
    updateProject(p => p.moveContentItem(activeId, overId));
  };

  const handleUpdateTitle = (id: string, newTitle: string, isChapter: boolean) => {
    if (isChapter) {
      updateProject(p => p.updateChapter(id, c => c.withProps({ title: newTitle })));
    } else {
      updateProject(p => p.updateSection(id, s => s.withProps({ title: newTitle })));
    }
  };

  const handleDeleteItem = (id: string, isChapter: boolean) => {
    if (isChapter) {
      updateProject(p => p.removeChapter(id));
    } else {
      const info = project?.findSection(id);
      if (info) {
        updateProject(p => p.updateChapter(info.chapter.id, c => c.removeSection(id)));
      }
    }
  };

  const handleAddChapter = (title = "New Chapter") => {
    updateProject(p => p.addChapter(uuidv4(), title));
  };

  const handleAddSection = (chapterId: string, title = "New Section") => {
    updateProject(p => p.addSectionToChapter(chapterId, uuidv4(), title));
  };

  const handleDuplicateItem = (id: string, isChapter: boolean) => {
    updateProject(p => (isChapter ? p.duplicateChapter(id, uuidv4) : p.duplicateSection(id, uuidv4)));
  };

  const handleCopyItem = (id: string, isChapter: boolean) => {
    if (!project) return;

    if (isChapter) {
      const chapter = project.getChapter(id);
      if (chapter) setClipboard({ type: 'chapter', data: chapter.toProperties() });
    } else {
      const info = project.findSection(id);
      if (info) setClipboard({ type: 'section', data: info.section.toProperties() });
    }
    toast({ title: 'Copied', description: 'Item copied to outline clipboard.' });
  };

  const handlePasteItem = (targetId: string, targetIsChapter: boolean) => {
    if (!clipboard || !project) return;

    updateProject(p => {
      const newId = uuidv4();

      if (clipboard.type === 'chapter') {
        const newChapterProps = {
          ...clipboard.data,
          id: newId,
          title: `${clipboard.data.title} (Copy)`,
        };
        if (newChapterProps.sections) {
          newChapterProps.sections = newChapterProps.sections.map((s: any) => ({ ...s, id: uuidv4() }));
        }
        const newChapter = new Chapter(newChapterProps);

        let insertionIndex = -1;
        if (targetIsChapter) {
          insertionIndex = p.content.findIndex(c => c.id === targetId);
        } else {
          const info = p.findSection(targetId);
          if (info) insertionIndex = p.content.findIndex(c => c.id === info.chapter.id);
        }

        if (insertionIndex !== -1) {
          const newContent = [...p.content];
          newContent.splice(insertionIndex + 1, 0, newChapter);
          return p.withProps({ content: newContent });
        }
      } else if (clipboard.type === 'section') {
        const newSectionProps = {
          ...clipboard.data,
          id: newId,
          title: `${clipboard.data.title} (Copy)`,
        };
        const newSection = new Section(newSectionProps);

        if (targetIsChapter) {
          return p.updateChapter(targetId, c => c.addSection(newSection, 0));
        } else {
          const info = p.findSection(targetId);
          if (info) {
            return p.updateChapter(info.chapter.id, c => c.addSection(newSection, info.sectionIndex + 1));
          }
        }
      }
      return p;
    });
    toast({ title: 'Pasted', description: `Successfully pasted ${clipboard.type}.` });
  };

  return {
    handleMoveItem,
    handleUpdateTitle,
    handleDeleteItem,
    handleAddChapter,
    handleAddSection,
    handleDuplicateItem,
    handleCopyItem,
    handlePasteItem,
    undo,
    clipboard
  };
};

'use client';

import React, { useMemo, useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  DndContext, 
  closestCenter, 
  KeyboardSensor, 
  PointerSensor, 
  useSensor, 
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import { 
  SortableContext, 
  sortableKeyboardCoordinates, 
  verticalListSortingStrategy
} from '@dnd-kit/sortable';
import { Search, X, Plus } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Project } from '@/modules/projects/domain/entities/Project';
import { Chapter } from '@/modules/ai-content/domain/entities/Chapter';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { SortableOutlineItem } from './SortableOutlineItem';
import { useOutlineOperations } from './useOutlineOperations';

/**
 * ProjectOutlineHUD — A high-fidelity, interactive document map for the Intelligence Suite.
 * Positioned as a floating layer for rapid navigation and structural management.
 */

interface ProjectOutlineHUDProps {
  isVisible: boolean;
  project: Project | null;
  activeChapterId: string | null;
  selectedSectionIds: string[];
  onActiveChapterChange: (id: string | null) => void;
  onActiveSectionChange: (id: string | null) => void;
}

export const ProjectOutlineHUD = ({
  isVisible,
  project,
  activeChapterId,
  selectedSectionIds,
  onActiveChapterChange,
  onActiveSectionChange,
}: ProjectOutlineHUDProps) => {
  const [expandedChapters, setExpandedChapters] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');

  const {
    handleMoveItem,
    handleUpdateTitle,
    handleDeleteItem,
    handleAddChapter,
    handleAddSection,
    handleDuplicateItem,
    handleCopyItem,
    handlePasteItem,
    undo,
    clipboard
  } = useOutlineOperations(project);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  // High-Density Workflow Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (!isVisible) return;

        const isMod = e.metaKey || e.ctrlKey;
        const activeId = activeChapterId || (selectedSectionIds.length > 0 ? selectedSectionIds[0] : null);
        const isChapter = !!activeChapterId;

        if (isMod && e.key === 'z') {
            e.preventDefault();
            undo();
        }

        if (activeId) {
            if (isMod && e.key === 'd') {
                e.preventDefault();
                handleDuplicateItem(activeId, isChapter);
            }
            if (isMod && e.key === 'c') {
                e.preventDefault();
                handleCopyItem(activeId, isChapter);
            }
            if (isMod && e.key === 'v') {
                e.preventDefault();
                handlePasteItem(activeId, isChapter);
            }
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isVisible, activeChapterId, selectedSectionIds, undo, handleDuplicateItem, handleCopyItem, handlePasteItem]);

  const toggleChapter = (id: string) => {
    setExpandedChapters(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const handleItemClick = (id: string, isChapter: boolean) => {
    if (isChapter) {
        onActiveChapterChange(id);
    } else {
        onActiveSectionChange(id);
    }

    // Coordinate scroll state with the document canvas
    setTimeout(() => {
        const element = document.getElementById(`item-${id}`);
        if (element) {
            element.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }, 100);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      handleMoveItem(active.id.toString(), over.id.toString());
    }
  };

  if (!project) return null;

  // Tactical Structural Filtering
  const filteredChapters = useMemo(() => {
    if (!searchQuery.trim()) return project.chapters as readonly Chapter[];

    const query = searchQuery.toLowerCase();
    return (project.chapters as readonly Chapter[]).filter(chapter => {
        const chapterMatches = chapter.title.toLowerCase().includes(query);
        const sectionsMatch = chapter.sections.some(s => s.title.toLowerCase().includes(query));
        return chapterMatches || sectionsMatch;
    });
  }, [project.chapters, searchQuery]);

  const allSortableIds = useMemo(() => {
    const ids: string[] = [];
    filteredChapters.forEach(c => {
      ids.push(c.id);
      if (expandedChapters.has(c.id) || searchQuery.trim()) {
        c.sections.forEach(s => {
            if (!searchQuery.trim() || s.title.toLowerCase().includes(searchQuery.toLowerCase()) || c.title.toLowerCase().includes(searchQuery.toLowerCase())) {
                ids.push(s.id);
            }
        });
      }
    });
    return ids;
  }, [filteredChapters, expandedChapters, searchQuery]);

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 0, x: -20, scale: 0.95 }}
          animate={{ opacity: 1, x: 0, scale: 1 }}
          exit={{ opacity: 0, x: -20, scale: 0.95 }}
          transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
          className="absolute top-20 left-8 z-[50] w-80 max-h-[calc(100vh-12rem)] overflow-hidden flex flex-col bg-background/60 backdrop-blur-3xl border border-primary/10 rounded-[32px] shadow-[0_12px_48px_rgba(0,0,0,0.12)]"
        >
          {/* HUD Header — Architectural Pulse */}
          <div className="px-5 py-4 border-b border-primary/10 space-y-4 bg-primary/[0.03]">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2.5">
                  <div className="h-1.5 w-1.5 rounded-full bg-primary animate-pulse shadow-[0_0_8px_rgba(var(--primary),0.6)]" />
                  <h3 className="text-[11px] font-black uppercase tracking-[0.22em] text-primary">Project Outline</h3>
                </div>
                <div className="flex items-center gap-4">
                    <span className="text-[9px] font-bold text-muted-foreground/30 uppercase tracking-[0.2em]">
                        {project.sections.length} NODES
                    </span>
                    <Button 
                        variant="ghost" 
                        size="icon" 
                        className="h-7 w-7 rounded-xl bg-primary/10 text-primary border border-primary/20 hover:bg-primary/20 transition-all hover:scale-110 active:scale-95 shadow-sm"
                        onClick={(e) => { e.stopPropagation(); handleAddChapter(); }}
                    >
                        <Plus className="h-4 w-4" />
                    </Button>
                </div>
            </div>

            {/* Tactical Search HUD */}
            <div className="relative group/search">
                <Input 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="SCAN STRUCTURE..."
                    className="h-9 pl-9 pr-9 text-[10px] bg-muted/5 border-primary/5 focus-visible:border-primary/20 focus-visible:ring-primary/10 rounded-2xl transition-all uppercase font-bold tracking-widest placeholder:text-muted-foreground/30"
                />
                <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground/20 group-focus-within/search:text-primary transition-colors" />
                {searchQuery && (
                    <button 
                        onClick={() => setSearchQuery('')}
                        className="absolute right-3.5 top-1/2 -translate-y-1/2 hover:text-primary transition-colors text-muted-foreground/40"
                    >
                        <X className="h-3.5 w-3.5" />
                    </button>
                )}
            </div>
          </div>

          {/* Primary Outline Control Layer */}
          <div className="flex-1 overflow-auto px-2 py-3 custom-scrollbar">
            <DndContext 
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragEnd={handleDragEnd}
            >
              <SortableContext 
                items={allSortableIds}
                strategy={verticalListSortingStrategy}
              >
                {filteredChapters.map((chapter, cIdx) => (
                  <SortableOutlineItem
                    key={chapter.id}
                    id={chapter.id}
                    index={cIdx}
                    title={chapter.title}
                    isActive={activeChapterId === chapter.id}
                    isChapter={true}
                    isExpanded={expandedChapters.has(chapter.id) || !!searchQuery.trim()}
                    hasContent={chapter.sections.some((s: Section) => !!s.content)}
                    onActivate={() => handleItemClick(chapter.id, true)}
                    onToggleExpand={() => toggleChapter(chapter.id)}
                    onUpdateTitle={(newTitle) => handleUpdateTitle(chapter.id, newTitle, true)}
                    onDelete={() => handleDeleteItem(chapter.id, true)}
                  >
                    {(chapter.sections as Section[])
                      .filter(s => !searchQuery.trim() || s.title.toLowerCase().includes(searchQuery.toLowerCase()) || chapter.title.toLowerCase().includes(searchQuery.toLowerCase()))
                      .map((section, sIdx) => (
                      <SortableOutlineItem
                        key={section.id}
                        id={section.id}
                        index={sIdx}
                        title={section.title}
                        isActive={selectedSectionIds.includes(section.id)}
                        hasContent={!!section.content}
                        onActivate={() => handleItemClick(section.id, false)}
                        onUpdateTitle={(newTitle) => handleUpdateTitle(section.id, newTitle, false)}
                        onDelete={() => handleDeleteItem(section.id, false)}
                      />
                    ))}
                    {!searchQuery && (
                        <div 
                            className="ml-4 mt-2 mb-3 px-3 py-2 flex items-center gap-2.5 rounded-xl border border-dashed border-primary/20 bg-primary/[0.02] hover:bg-primary/[0.05] transition-all cursor-pointer group/add active:scale-[0.98]"
                            onClick={(e) => { e.stopPropagation(); handleAddSection(chapter.id); }}
                        >
                            <div className="h-5 w-5 rounded-lg bg-primary/5 flex items-center justify-center border border-primary/10 group-hover/add:border-primary/30 transition-all">
                                <Plus className="h-3 w-3 text-primary/40 group-hover/add:text-primary transition-colors" />
                            </div>
                            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/40 group-hover/add:text-primary transition-colors">Integrate Node</span>
                        </div>
                    )}
                  </SortableOutlineItem>
                ))}
              </SortableContext>
            </DndContext>
          </div>

          {/* HUD Metadata Footer */}
          <div className="px-5 py-2.5 bg-background/40 border-t border-primary/10 flex items-center justify-between backdrop-blur-2xl">
             <div className="flex items-center gap-2">
                 <div className="h-1.5 w-1.5 rounded-full bg-primary/20" />
                 <p className="text-[9px] font-black uppercase tracking-[0.2em] text-muted-foreground/40">
                    Structure Manifest
                 </p>
             </div>
             <div className="flex items-center gap-2 px-2 py-0.5 rounded-full bg-green-500/5 border border-green-500/10">
                <div className="h-1 w-1 rounded-full bg-green-500 animate-pulse" />
                <p className="text-[9px] font-black uppercase tracking-[0.15em] text-green-600/60">Active Core</p>
             </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

ProjectOutlineHUD.displayName = 'ProjectOutlineHUD';

'use client';

import React, { useMemo, useState, useEffect } from 'react';
import { 
  DndContext, 
  closestCenter, 
  KeyboardSensor, 
  PointerSensor, 
  useSensor, 
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import { 
  SortableContext, 
  sortableKeyboardCoordinates, 
  verticalListSortingStrategy
} from '@dnd-kit/sortable';
import { Search, X, Plus } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useBuilderStore } from '@/hooks';
import { Chapter } from '@/modules/ai-content/domain/entities/Chapter';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { SortableOutlineItem } from './SortableOutlineItem';
import { useOutlineOperations } from './useOutlineOperations';

/**
 * SidebarOutlineManager — A docked structural navigator for the side panel.
 * Refactored to use shared outline primitives and consolidated project logic.
 */

interface SidebarOutlineManagerProps {
  activeChapterId: string | null;
  selectedSectionIds: string[];
  onActiveChapterChange: (id: string | null) => void;
  onActiveSectionChange: (id: string | null, multiSelect?: boolean) => void;
}

export function SidebarOutlineManager({
  activeChapterId,
  selectedSectionIds,
  onActiveChapterChange,
  onActiveSectionChange,
}: SidebarOutlineManagerProps) {
  const { project, syncProjectStructure } = useBuilderStore(state => ({
    project: state.project,
    syncProjectStructure: state.syncProjectStructure,
  }));

  const {
    handleMoveItem,
    handleUpdateTitle,
    handleDeleteItem,
    handleAddChapter,
    handleAddSection,
    handleDuplicateItem,
    handleCopyItem,
    handlePasteItem,
    undo
  } = useOutlineOperations(project);

  // Sync structural cache on mount
  useEffect(() => {
    syncProjectStructure();
  }, [syncProjectStructure]);

  const [expandedChapters, setExpandedChapters] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  // Integrated Keyboard Logic for Sidebar
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const isMod = e.metaKey || e.ctrlKey;
      const activeId = activeChapterId || (selectedSectionIds.length > 0 ? selectedSectionIds[0] : null);
      const isChapter = !!activeChapterId;

      if (isMod && e.key === 'z') {
        e.preventDefault();
        undo();
      }

      if (!activeId) return;

      if (isMod && e.key === 'd') {
        e.preventDefault();
        handleDuplicateItem(activeId, isChapter);
      }
      if (isMod && e.key === 'c') {
        e.preventDefault();
        handleCopyItem(activeId, isChapter);
      }
      if (isMod && e.key === 'v') {
        e.preventDefault();
        handlePasteItem(activeId, isChapter);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeChapterId, selectedSectionIds, undo, handleDuplicateItem, handleCopyItem, handlePasteItem]);

  const toggleChapter = (id: string) => {
    setExpandedChapters(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const handleItemClick = (id: string, isChapter: boolean) => {
    if (isChapter) {
      onActiveChapterChange(id);
    } else {
      onActiveSectionChange(id);
    }
    setTimeout(() => {
      const element = document.getElementById(`item-${id}`);
      if (element) element.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      handleMoveItem(active.id.toString(), over.id.toString());
    }
  };

  if (!project) return null;

  // Optimized Search for High-Density Sidebar
  const filteredChapters = useMemo(() => {
    if (!searchQuery.trim()) return project.chapters as readonly Chapter[];
    const query = searchQuery.toLowerCase();
    return (project.chapters as readonly Chapter[]).filter(chapter => {
      return (
        chapter.title.toLowerCase().includes(query) ||
        chapter.sections.some(s => s.title.toLowerCase().includes(query))
      );
    });
  }, [project.chapters, searchQuery]);

  const allSortableIds = useMemo(() => {
    const ids: string[] = [];
    filteredChapters.forEach(c => {
      ids.push(c.id);
      if (expandedChapters.has(c.id) || searchQuery.trim()) {
        c.sections.forEach(s => {
          if (
            !searchQuery.trim() ||
            s.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            c.title.toLowerCase().includes(searchQuery.toLowerCase())
          ) {
            ids.push(s.id);
          }
        });
      }
    });
    return ids;
  }, [filteredChapters, expandedChapters, searchQuery]);

  return (
    <div className="flex flex-col h-full gap-4">
      {/* Sidebar HUD Header */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="h-1 w-1 rounded-full bg-primary/40 shadow-[0_0_8px_rgba(var(--primary),0.4)]" />
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/80">
              Nav Structure
            </h3>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-[8px] font-bold text-muted-foreground/30 uppercase tracking-widest tabular-nums">
              {project.sections.length} Units
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="h-6 w-6 rounded-lg bg-primary/5 text-primary/60 border border-primary/10 hover:bg-primary/10 transition-all hover:scale-105"
              onClick={(e) => {
                e.stopPropagation();
                handleAddChapter();
              }}
            >
              <Plus className="h-3.5 w-3.5" />
            </Button>
          </div>
        </div>

        {/* Dense Search HUD */}
        <div className="relative group/search">
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="SCAN OUTLINE..."
            className="h-8 pl-8 pr-8 text-[9px] bg-muted/5 border-primary/5 focus-visible:ring-primary/10 focus-visible:border-primary/20 rounded-xl transition-all font-bold uppercase tracking-widest"
          />
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground/30 group-focus-within/search:text-primary transition-colors" />
          {searchQuery && (
            <button
              onClick={() => setSearchQuery('')}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 hover:text-primary transition-colors text-muted-foreground/40"
            >
              <X className="h-3 w-3" />
            </button>
          )}
        </div>
      </div>

      {/* Main Navigator List — Independent ScrollArea */}
      <ScrollArea className="flex-1 min-h-0 -mx-1 px-1">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext items={allSortableIds} strategy={verticalListSortingStrategy}>
            {filteredChapters.map((chapter, cIdx) => (
              <SortableOutlineItem
                key={chapter.id}
                id={chapter.id}
                index={cIdx}
                title={chapter.title}
                isActive={activeChapterId === chapter.id}
                isChapter={true}
                isExpanded={expandedChapters.has(chapter.id) || !!searchQuery.trim()}
                hasContent={chapter.sections.some((s: Section) => !!s.content)}
                onActivate={() => handleItemClick(chapter.id, true)}
                onToggleExpand={() => toggleChapter(chapter.id)}
                onUpdateTitle={(newTitle) => handleUpdateTitle(chapter.id, newTitle, true)}
                onDelete={() => handleDeleteItem(chapter.id, true)}
              >
                {(chapter.sections as Section[])
                  .filter(
                    s =>
                      !searchQuery.trim() ||
                      s.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                      chapter.title.toLowerCase().includes(searchQuery.toLowerCase())
                  )
                  .map((section, sIdx) => (
                    <SortableOutlineItem
                      key={section.id}
                      id={section.id}
                      index={sIdx}
                      title={section.title}
                      isActive={selectedSectionIds.includes(section.id)}
                      hasContent={!!section.content}
                      onActivate={() => handleItemClick(section.id, false)}
                      onUpdateTitle={(newTitle) => handleUpdateTitle(section.id, newTitle, false)}
                      onDelete={() => handleDeleteItem(section.id, false)}
                    />
                  ))}
                {!searchQuery && (
                  <div
                    className="ml-4 mt-1 mb-2 px-2 py-1.5 flex items-center gap-2 rounded-xl border border-dashed border-primary/10 bg-primary/[0.01] hover:bg-primary/[0.03] transition-all cursor-pointer group/add active:scale-[0.98]"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleAddSection(chapter.id);
                    }}
                  >
                    <Plus className="h-3 w-3 text-primary/30 group-hover/add:text-primary transition-colors" />
                    <span className="text-[9px] font-black uppercase tracking-[0.2em] text-primary/30 group-hover/add:text-primary transition-colors">
                      Integrate Node
                    </span>
                  </div>
                )}
              </SortableOutlineItem>
            ))}
          </SortableContext>
        </DndContext>
      </ScrollArea>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { ChevronRight, MoreHorizontal } from 'lucide-react';
import { cn } from '@/infrastructure/utils/cn';

/**
 * SidebarSection — A reusable collapsible grouping for side panels.
 * Features a high-density VSCode-style technical header and animated expansion.
 */

interface SidebarSectionProps {
  title: string;
  defaultOpen?: boolean;
  actions?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
}

export function SidebarSection({
  title,
  defaultOpen = true,
  actions,
  children,
  className,
}: SidebarSectionProps) {
  const [isOpen, setIsOpen] = useState(defaultOpen);

  return (
    <div className={cn('flex flex-col', className)}>
      {/* Group Header — High-Density Technical Look */}
      <button
        type="button"
        onClick={() => setIsOpen(prev => !prev)}
        className={cn(
          'flex w-full items-center gap-2 px-3 py-2 text-start transition-all duration-300',
          'border-b border-primary/10 bg-primary/[0.02] hover:bg-primary/[0.05]',
          'focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-primary/30 group/section'
        )}
      >
        <ChevronRight
          className={cn(
            'h-3 w-3 shrink-0 text-muted-foreground/40 transition-transform duration-500 ease-[0.22,1,0.36,1]',
            isOpen && 'rotate-90 text-primary/60'
          )}
        />

        {/* Technical Label */}
        <span className="text-[9px] font-black uppercase tracking-[0.25em] text-muted-foreground/70 flex-1 group-hover/section:text-primary/80 transition-colors">
          {title}
        </span>

        {/* Action HUD */}
        {actions ? (
            <div className="flex items-center gap-1 shrink-0">
                {actions}
            </div>
        ) : (
            <MoreHorizontal className="h-3 w-3 text-muted-foreground/20 group-hover/section:text-primary/30 transition-colors" />
        )}
      </button>

      {/* Animated Content Slot */}
      <AnimatePresence initial={false}>
        {isOpen && (
          <motion.div
            key="section-body"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
            className="overflow-hidden"
          >
            <div className="p-4 flex flex-col gap-4 relative">
              {/* Subtle vertical architectural line */}
              <div className="absolute left-3.5 inset-y-0 w-px bg-primary/[0.03]" aria-hidden />

              <div className="relative z-10">
                {children}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

