'use client';

import React from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { cn } from '@/infrastructure/utils/cn';
import { GripVertical, Loader2 } from 'lucide-react';
import { Checkbox } from '@/components/ui/checkbox';

/**
 * GenerationNodeItem — A shared high-fidelity component for sortable AI nodes.
 * Used for both Chapters and Sections in the GenerationNavigator.
 */

interface GenerationNodeItemProps {
  id: string;
  index: number;
  labelIndex?: string; // e.g. "1.2"
  title: string;
  isActive: boolean;
  isDraggingEnabled?: boolean;
  isGenerating?: boolean;
  isSelectionMode?: boolean;
  isSelected?: boolean;
  level?: 0 | 1;
  onActivate: (id: string, multiSelect?: boolean) => void;
  onToggleSelection?: (id: string) => void;
  extra?: React.ReactNode;
  className?: string;
}

export const GenerationNodeItem = ({
  id,
  index,
  labelIndex,
  title,
  isActive,
  isDraggingEnabled = true,
  isGenerating = false,
  isSelectionMode = false,
  isSelected = false,
  level = 0,
  onActivate,
  onToggleSelection,
  extra,
  className,
}: GenerationNodeItemProps) => {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id,
    disabled: !isDraggingEnabled,
  });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 50 : 'auto',
    position: 'relative',
  };

  const handleActivate = (e: React.MouseEvent) => {
    onActivate(id, e.shiftKey || e.metaKey || e.ctrlKey);
  };

  const handleCheckboxClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    onToggleSelection?.(id);
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        'group/item relative rounded-xl border transition-all duration-300 ease-out',
        level === 1 && 'ml-4',
        isActive
          ? 'border-primary/30 bg-primary/[0.03] shadow-[0_4px_20px_rgba(var(--primary),0.08)] ring-1 ring-primary/20 -translate-y-[0.5px]'
          : 'border-border/40 bg-card/50 shadow-sm hover:border-primary/20 hover:bg-muted/5 hover:translate-x-0.5',
        className
      )}
    >
      <div
        className="flex items-center gap-2 px-3 py-2 cursor-pointer select-none"
        onClick={handleActivate}
      >
        {/* Selection HUD — Only visible in bulk mode */}
        {isSelectionMode && (
          <div className="shrink-0 mr-1" onClick={handleCheckboxClick}>
            <Checkbox
              checked={isSelected}
              className="h-3.5 w-3.5 rounded-sm border-muted-foreground/30 data-[state=checked]:bg-primary data-[state=checked]:border-primary transition-all duration-300"
            />
          </div>
        )}

        {/* Technical ID + Drag Handle */}
        {isDraggingEnabled && listeners && (
          <div
            {...listeners}
            {...attributes}
            className="flex items-center gap-1 shrink-0 text-muted-foreground/40 transition-colors hover:text-primary cursor-grab active:cursor-grabbing"
            onClick={e => e.stopPropagation()}
          >
            <span className={cn(
                "text-[9px] font-black uppercase tracking-[0.2em] w-7 text-center tabular-nums opacity-60 transition-colors duration-300",
                isActive && "opacity-100 text-primary"
            )}>
              {labelIndex || (index + 1).toString().padStart(2, '0')}
            </span>
            <GripVertical className="h-3.5 w-3.5 opacity-40 group-hover/item:opacity-100 transition-opacity ml-1" />
          </div>
        )}

        {/* Core Node Logic */}
        <div className="flex items-center gap-2.5 flex-1 min-w-0">
          {isGenerating ? (
            <div className="relative shrink-0">
              <Loader2 className="h-3.5 w-3.5 animate-spin text-primary" />
              <div className="absolute inset-0 blur-sm bg-primary/20 animate-pulse rounded-full" />
            </div>
          ) : (
            <div
              className={cn(
                'h-1.5 w-1.5 rounded-full shrink-0 transition-all duration-500',
                isActive
                  ? 'bg-primary scale-125 shadow-[0_0_12px_rgba(var(--primary),0.8)] animate-pulse'
                  : 'bg-muted-foreground/20'
              )}
            />
          )}

          <span
            className={cn(
              'text-[11px] font-bold tracking-tight truncate flex-1 transition-colors duration-300',
              isActive ? 'text-foreground' : 'text-muted-foreground/80 group-hover/item:text-foreground',
              level === 0 && 'font-black uppercase tracking-wider text-[10px]'
            )}
          >
            {title || (level === 0 ? 'Untitled Chapter' : 'Untitled Section')}
          </span>
        </div>

        {/* Dynamic Contextual Layer (Badges, etc) */}
        {extra && (
            <div className="shrink-0 ml-1">
                {extra}
            </div>
        )}
      </div>
    </div>
  );
};

'use client';

import React from 'react';
import { ClipboardPaste, Copy, Link as LinkIcon, SlidersHorizontal, Sparkles, Square, StickyNote, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/infrastructure/utils/cn';
import { useLocalization } from '@/context/LocalizationContext';
import { useBuilderStore } from '@/hooks';
import { useGenerationUIStore } from '@/modules/ai-content/adapters/state/useGenerationUIStore';
import { useAiActions } from '@/modules/ai-content/adapters/hooks/report-mode/use-ai-actions';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { GuidelineEditor } from '@/modules/ai-content/adapters/components/report-mode/section-controls/SectionGuidelineEditor';
import { SectionContextSelector } from '@/modules/ai-content/adapters/components/report-mode/section-controls/SectionContextSelector';
import { SectionGenerationControls } from '@/modules/ai-content/adapters/components/report-mode/section-controls/SectionGenerationControls';
import { SidebarContainer } from '../layout/SidebarContainer';

/**
 * SectionGenerationHUD — Context-sensitive AI operations for Sections.
 * Supports both single-focus and bulk generation modes with high-fidelity HUD styling.
 */

interface SectionGenerationHUDProps {
    section: Section | null;
    selectedSectionIds?: string[];
    className?: string;
}

export function SectionGenerationHUD({ section, selectedSectionIds = [], className }: SectionGenerationHUDProps) {
    const { t } = useLocalization();
    const { project, updateProject } = useBuilderStore();
    const { generateSectionMutation, generateChapterMutation, generateProjectMutation } = useAiActions();
    const { clipboard, copySettings } = useGenerationUIStore();

    const estimatedRemaining = React.useMemo(() => {
        if (!generateProjectMutation.isPending && !generateChapterMutation.isPending) return null;
        const stats = generateProjectMutation.isPending
            ? (generateProjectMutation.variables as any)?.project?.getStats()
            : (generateChapterMutation.variables as any)?.chapter?.getStats();

        if (!stats) return null;
        const remaining = stats.total - stats.completed;
        if (remaining <= 0) return null;

        const seconds = remaining * 12;
        if (seconds < 60) return `~${seconds} seconds remaining`;
        return `~${Math.ceil(seconds / 60)} minutes remaining`;
    }, [generateProjectMutation, generateChapterMutation]);

    if (!section) {
        return (
            <SidebarContainer title="Section Tools" icon={<Sparkles className="h-3.5 w-3.5" />}>
                <div className="flex flex-col items-center justify-center h-64 text-center space-y-4 opacity-40">
                    <div className="p-5 rounded-[24px] bg-primary/5 border border-primary/10 shadow-inner">
                        <Sparkles className="h-8 w-8 text-primary/40" />
                    </div>
                    <div className="space-y-1.5 px-6">
                        <p className="text-[10px] font-black uppercase tracking-[0.25em] text-muted-foreground">No selection</p>
                        <p className="text-[11px] font-medium leading-relaxed italic text-muted-foreground/60 max-w-[200px]">
                            Select a node in the document to configure neural generation parameters.
                        </p>
                    </div>
                </div>
            </SidebarContainer>
        );
    }

    const isBulkGeneration = selectedSectionIds.length > 1;
    const isGenerating = isBulkGeneration
        ? generateProjectMutation.isPending || generateChapterMutation.isPending
        : generateSectionMutation.isPending && (generateSectionMutation.variables as any) === section.id;

    const isAnythingGenerating = generateSectionMutation?.isPending || generateChapterMutation.isPending || generateProjectMutation.isPending;
    const canGenerate = !isAnythingGenerating; // Credits handled server-side
    const creditCost = isBulkGeneration ? selectedSectionIds.length : 1;

    const handleCopySettings = () => {
        if (!section) return;
        copySettings({
            controls: { ...section.controls },
            context: { ...section.context },
            guidelines: [...section.guidelines]
        });
    };

    const handlePasteSettings = () => {
        if (!section || !clipboard) return;
        const targets = isBulkGeneration ? selectedSectionIds : [section.id];
        updateProject(p => {
            targets.forEach(id => {
                p.updateSection(id, s => s.withProps({
                    controls: { ...(clipboard.controls as any) },
                    context: { ...(clipboard.context as any) },
                    guidelines: [...(clipboard.guidelines || [])]
                }));
            });
        });
    };

    const bulkProgress = generateProjectMutation.isPending ? (generateProjectMutation.variables as any)?.project?.getStats().completed ?? 0 : (generateChapterMutation.variables as any)?.chapter?.getStats().completed ?? 0;
    const bulkTotal = isBulkGeneration ? selectedSectionIds.length : 1;
    const isBulkGenerating = (generateProjectMutation.isPending || generateChapterMutation.isPending) && isBulkGeneration;

    const handleGenerateClick = () => {
        if (!section) return;
        if (isBulkGenerating || isGenerating) return;

        if (isBulkGeneration) {
            generateProjectMutation.mutate({ project: project!, selectedSectionIds: new Set(selectedSectionIds) });
        } else {
            generateSectionMutation.mutate(section.id);
        }
    };

    return (
        <SidebarContainer
            title={isBulkGeneration ? `Bulk Production (${selectedSectionIds.length})` : 'Section Synthesis'}
            icon={<Sparkles className="h-3.5 w-3.5" />}
            actions={
                <div className="flex items-center gap-1 p-1 rounded-xl bg-background/20 border border-primary/5 backdrop-blur-md shadow-inner">
                    <TooltipProvider delayDuration={200}>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-7 w-7 text-muted-foreground hover:text-primary hover:bg-primary/5 transition-all rounded-lg"
                                    onClick={handleCopySettings}
                                >
                                    <Copy className="h-3.5 w-3.5" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-widest bg-background/95 backdrop-blur-md border-primary/20 mt-2">
                                Copy Logic
                            </TooltipContent>
                        </Tooltip>

                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-7 w-7 text-muted-foreground hover:text-primary hover:bg-primary/5 transition-all rounded-lg"
                                    onClick={handlePasteSettings}
                                    disabled={!clipboard}
                                >
                                    <ClipboardPaste className="h-3.5 w-3.5" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-widest bg-background/95 backdrop-blur-md border-primary/20 mt-2">
                                Paste Logic
                            </TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                </div>
            }
        >
            <div className="space-y-8 relative">
                {/* Node Identity Zone */}
                <div className="flex flex-col gap-5">
                    <div className="space-y-1.5 px-1">
                        <span className="text-[9px] font-black uppercase tracking-[0.25em] text-primary/60">
                            {isBulkGeneration ? 'Integrated Cluster' : 'Synthesis Target'}
                        </span>
                        <h3 className="text-[13px] font-black uppercase truncate tracking-widest text-foreground/90 tabular-nums">
                            {isBulkGeneration ? 'Multiple Section Block' : section.title}
                        </h3>
                    </div>

                    {isBulkGenerating && (
                        <div className="space-y-3.5 p-5 rounded-2xl bg-primary/[0.03] border border-primary/10 shadow-sm animate-in fade-in slide-in-from-top-2 duration-500">
                            <div className="flex justify-between items-end">
                                <div className="flex flex-col gap-1">
                                    <span className="text-[9px] font-black uppercase tracking-widest text-primary/70 leading-none">System Processing</span>
                                    {estimatedRemaining && (
                                        <span className="text-[8px] font-bold text-muted-foreground/60 uppercase tracking-wider mt-1">{estimatedRemaining}</span>
                                    )}
                                </div>
                                <span className="text-[10px] font-mono font-bold text-primary tabular-nums">{bulkProgress} / {bulkTotal}</span>
                            </div>
                            <Progress value={(bulkProgress / bulkTotal) * 100} className="h-1 bg-primary/10" />
                        </div>
                    )}

                    <TooltipProvider>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button
                                    onClick={handleGenerateClick}
                                    disabled={!canGenerate && !isBulkGenerating && !isGenerating}
                                    variant={(isBulkGenerating || (isGenerating && !isBulkGeneration)) ? "destructive" : "default"}
                                    className={cn(
                                        "w-full font-black h-12 gap-2.5 shadow-2xl shadow-primary/15 rounded-2xl uppercase tracking-[0.2em] text-[10px] relative overflow-hidden group/gen",
                                        !(isBulkGenerating || (isGenerating && !isBulkGeneration)) && "bg-primary hover:opacity-90 ring-1 ring-inset ring-white/20"
                                    )}
                                >
                                    {isBulkGenerating ? (
                                        <>
                                            <Square className="h-4 w-4 fill-current" />
                                            <span>Terminate Batch</span>
                                        </>
                                    ) : isGenerating ? (
                                        <>
                                            <Loader2 className="h-4 w-4 animate-spin" />
                                            <span>Abort Synthesis</span>
                                        </>
                                    ) : (
                                        <>
                                            <Sparkles className="h-4 w-4 shrink-0 transition-transform group-hover/gen:scale-110" />
                                            <span>
                                                {isBulkGeneration
                                                    ? `Generate ${selectedSectionIds.length} Nodes`
                                                    : 'Synthesize Section'}
                                            </span>
                                        </>
                                    )}
                                    <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/15 to-white/0 -translate-x-full group-hover/gen:translate-x-full transition-transform duration-1000 ease-in-out" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-widest bg-background/95 backdrop-blur-md border-primary/20 mt-3">
                                {isBulkGenerating ? 'Stop current pipeline' : `Neural Cost: ${creditCost} Energy`}
                            </TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                </div>

                {/* Synthesis Parameter Zone */}
                <Tabs defaultValue="context" className="w-full flex flex-col gap-6">
                    <TabsList className="grid w-full grid-cols-3 h-11 rounded-2xl bg-muted/20 p-1 gap-1 border border-border/40 backdrop-blur-md">
                        <TabsTrigger value="context" className="gap-2 text-[9px] font-black uppercase tracking-[0.15em] data-[state=active]:bg-background data-[state=active]:text-primary data-[state=active]:shadow-lg px-2 transition-all rounded-xl">
                            <LinkIcon className="h-3.5 w-3.5 shrink-0" />
                            <span className="truncate">Context</span>
                        </TabsTrigger>
                        <TabsTrigger value="prompt" className="gap-2 text-[9px] font-black uppercase tracking-[0.15em] data-[state=active]:bg-background data-[state=active]:text-primary data-[state=active]:shadow-lg px-2 transition-all rounded-xl">
                            <StickyNote className="h-3.5 w-3.5 shrink-0" />
                            <span className="truncate">Logic</span>
                        </TabsTrigger>
                        <TabsTrigger value="controls" className="gap-2 text-[9px] font-black uppercase tracking-[0.15em] data-[state=active]:bg-background data-[state=active]:text-primary data-[state=active]:shadow-lg px-2 transition-all rounded-xl">
                            <SlidersHorizontal className="h-3.5 w-3.5 shrink-0" />
                            <span className="truncate">Styles</span>
                        </TabsTrigger>
                    </TabsList>

                    <div className="relative min-h-[320px]">
                        <TabsContent value="context" className="m-0 focus-visible:ring-0 animate-in fade-in slide-in-from-right-4 duration-500">
                            <div className="space-y-5">
                                <span className="text-[9px] font-black uppercase tracking-widest text-muted-foreground/60 px-1">Source Matrices</span>
                                <SectionContextSelector
                                    sectionId={section.id}
                                    selectedSectionIds={selectedSectionIds.length > 1 ? selectedSectionIds : undefined}
                                />
                            </div>
                        </TabsContent>
                        <TabsContent value="prompt" className="m-0 focus-visible:ring-0 animate-in fade-in slide-in-from-right-4 duration-500">
                            <div className="space-y-5">
                                <span className="text-[9px] font-black uppercase tracking-widest text-muted-foreground/60 px-1">Neural Instructions</span>
                                <GuidelineEditor
                                    itemKey={section.id}
                                    selectedSectionIds={selectedSectionIds.length > 1 ? selectedSectionIds : undefined}
                                />
                            </div>
                        </TabsContent>
                        <TabsContent value="controls" className="m-0 focus-visible:ring-0 animate-in fade-in slide-in-from-right-4 duration-500">
                            <div className="space-y-5">
                                <span className="text-[9px] font-black uppercase tracking-widest text-muted-foreground/60 px-1">Structural Vector</span>
                                <SectionGenerationControls
                                    section={section}
                                    selectedSectionIds={selectedSectionIds.length > 1 ? selectedSectionIds : undefined}
                                />
                            </div>
                        </TabsContent>
                    </div>
                </Tabs>
            </div>

            {/* Stable Version Footer */}
            <div className="absolute bottom-0 left-0 right-0 px-6 py-3 border-t border-primary/10 bg-background/40 backdrop-blur-xl flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <div className="h-1 w-1 rounded-full bg-primary/30" />
                    <span className="text-[8px] font-black uppercase tracking-widest text-muted-foreground/40">Neural Synthesis Manifest</span>
                </div>
                <span className="text-[8px] font-bold text-muted-foreground/20 tabular-nums">v2.4.0-STABLE</span>
            </div>
        </SidebarContainer>
    );
}

'use client';

import React, { useMemo } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Building, ChevronRight, PlusCircle, Sparkles, XCircle, Zap } from 'lucide-react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useLocalization } from '@/context/LocalizationContext';
import { useReportGenerationTools } from '@/modules/ai-content/adapters/hooks/report-mode/use-report-generation-tools';
import { Chapter } from '@/modules/ai-content/domain/entities/Chapter';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { BuildProjectDialog } from '@/modules/ai-content/adapters/components/report-mode/dialogs/BuildProjectDialog';
import { SidebarContainer } from '../layout/SidebarContainer';
import { GenerationNodeItem } from './GenerationNodeItem';

/**
 * GenerationNavigator — Primary control hub for AI-driven project assembly.
 * Manages the document structure from an AI-orchestration perspective.
 */

interface GenerationNavigatorProps {
  selectedSectionIds: string[];
  activeChapterId?: string | null;
  onActiveSectionChange: (sectionId: string | null, multiSelect?: boolean) => void;
  onActiveChapterChange?: (chapterId: string | null) => void;
}

export function GenerationNavigator({
  selectedSectionIds,
  activeChapterId,
  onActiveSectionChange,
  onActiveChapterChange,
}: GenerationNavigatorProps) {
  const { t } = useLocalization();
  const {
    handleDragEnd,
    isBuildProjectDialogOpen,
    setIsBuildProjectDialogOpen,
    project,
    isProjectBuildMode,
    enterProjectBuildMode,
    exitProjectBuildMode,
    selectedSectionsForBuild,
    toggleChapterSelection,
    toggleSectionSelection,
    toggleSelectAll,
    onGenerateProject,
    projectMutation,
    chaptersToBuild,
    handleAddChapter,
    handleAddSection,
  } = useReportGenerationTools();

  const totalSelectableSections = project?.sections.length || 0;
  const isAllSelected = useMemo(
    () => totalSelectableSections > 0 && selectedSectionsForBuild.size === totalSelectableSections,
    [totalSelectableSections, selectedSectionsForBuild]
  );
  const isIndeterminate = useMemo(
    () => selectedSectionsForBuild.size > 0 && !isAllSelected,
    [selectedSectionsForBuild, isAllSelected]
  );

  const canBuildProject = project && project.content.length > 0;

  if (!project) return null;

  return (
    <>
      <BuildProjectDialog
        isOpen={isBuildProjectDialogOpen}
        onOpenChange={setIsBuildProjectDialogOpen}
        chaptersToBuild={chaptersToBuild}
        onGenerateProject={onGenerateProject}
        isLoading={projectMutation.isPending}
      />

      <SidebarContainer
        title="AI Production"
        icon={<Zap className="h-3.5 w-3.5" />}
        actions={
          <Button
            onClick={handleAddChapter}
            variant="ghost"
            size="icon"
            className="h-8 w-8 rounded-lg text-primary/60 transition-all hover:bg-primary/10 hover:text-primary hover:scale-110"
          >
            <PlusCircle className="h-4 w-4" />
          </Button>
        }
      >
        <div className="flex h-full flex-col gap-6">
          <div className="space-y-1.5">
            <p className="text-[10px] font-medium italic leading-relaxed text-muted-foreground/60 uppercase tracking-wider">
              Orchestrate the neural assembly of your project manifest.
            </p>
          </div>

          <AnimatePresence initial={false}>
            {isProjectBuildMode && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                className="overflow-hidden"
              >
                <div className="flex items-center gap-4 rounded-2xl border border-primary/20 bg-primary/[0.04] p-4 shadow-[0_8px_32px_rgba(var(--primary),0.12)] backdrop-blur-xl ring-1 ring-inset ring-white/10">
                  <div className="relative">
                    <Checkbox
                      id="select-all-nodes"
                      checked={isAllSelected}
                      onCheckedChange={(checked: boolean) => toggleSelectAll(!!checked)}
                      aria-checked={isIndeterminate ? 'mixed' : isAllSelected}
                      className="h-4.5 w-4.5 rounded-md border-primary/40 data-[state=checked]:bg-primary"
                    />
                    <Sparkles className="absolute -right-2 -top-2 h-3 w-3 text-primary animate-pulse" />
                  </div>
                  <div className="flex flex-col">
                    <Label
                      htmlFor="select-all-nodes"
                      className="cursor-pointer text-[10px] font-black uppercase tracking-[0.15em] text-primary"
                    >
                      Production Selection Mode
                    </Label>
                    <span className="mt-0.5 text-[9px] font-bold uppercase tracking-widest text-primary/50 tabular-nums">
                      {selectedSectionsForBuild.size} / {totalSelectableSections} Nodes Optimized
                    </span>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <ScrollArea className="flex-1 min-h-0 pr-1">
            <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
              <SortableContext
                items={(project.content || []).map((contentItem) => contentItem.id)}
                strategy={verticalListSortingStrategy}
              >
                <div className="space-y-4">
                  {(project.content || []).map((item, index) => {
                    const isChapter = item instanceof Chapter;
                    const isActive = isChapter ? activeChapterId === item.id : selectedSectionIds.includes(item.id);

                    return (
                      <div key={item.id} className="space-y-2">
                        <GenerationNodeItem
                          id={item.id}
                          index={index}
                          title={item.title}
                          isActive={isActive}
                          level={0}
                          isSelectionMode={isProjectBuildMode}
                          isSelected={isChapter 
                            ? (item.sections.length > 0 && item.sections.every(s => selectedSectionsForBuild.has(s.id))) 
                            : selectedSectionsForBuild.has(item.id)}
                          onActivate={(id) => isChapter ? onActiveChapterChange?.(id) : onActiveSectionChange(id)}
                          onToggleSelection={(id) => isChapter 
                            ? toggleChapterSelection(id, !(item.sections.every(s => selectedSectionsForBuild.has(s.id))))
                            : toggleSectionSelection(id)}
                        />

                        {isChapter && (
                          <div className="pl-4 space-y-2 relative">
                            {/* Depth architecture line */}
                            <div className="absolute left-2 top-0 bottom-4 w-px bg-gradient-to-b from-primary/20 via-primary/5 to-transparent" />

                            {item.sections.map((section, sIdx) => (
                              <GenerationNodeItem
                                key={section.id}
                                id={section.id}
                                index={sIdx}
                                labelIndex={`${index + 1}.${sIdx + 1}`}
                                title={section.title}
                                level={1}
                                isActive={selectedSectionIds.includes(section.id)}
                                isSelectionMode={isProjectBuildMode}
                                isSelected={selectedSectionsForBuild.has(section.id)}
                                onActivate={onActiveSectionChange}
                                onToggleSelection={toggleSectionSelection}
                              />
                            ))}

                            {!isProjectBuildMode && (
                              <button
                                onClick={() => handleAddSection(item.id)}
                                className="ml-4 w-[calc(100%-1rem)] h-8 flex items-center gap-2 px-3 rounded-xl border border-dashed border-primary/10 bg-primary/[0.01] hover:bg-primary/[0.03] transition-all group/add"
                              >
                                <PlusCircle className="h-3.5 w-3.5 text-primary/30 group-hover/add:text-primary/60 transition-colors" />
                                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-primary/30 group-hover/add:text-primary/60 transition-colors">
                                  Integrate Section
                                </span>
                              </button>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </SortableContext>
            </DndContext>
          </ScrollArea>

          <div className="pt-2">
            <AnimatePresence mode="wait">
              {isProjectBuildMode ? (
                <motion.div
                  key="build-mode-actions"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 12 }}
                  transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                  className="flex w-full gap-2.5"
                >
                  <Button
                    onClick={exitProjectBuildMode}
                    variant="secondary"
                    className="h-12 flex-1 rounded-2xl border border-primary/10 bg-background/60 font-black uppercase tracking-widest text-[9px] backdrop-blur-xl transition-all hover:bg-red-500/5 hover:text-red-600 hover:border-red-500/20"
                  >
                    <XCircle className="mr-2 h-4 w-4" /> Terminate
                  </Button>
                  <Button
                    className="h-12 flex-[2] rounded-2xl bg-primary text-[10px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-primary/20 transition-all hover:opacity-90 ring-1 ring-inset ring-white/20"
                    onClick={() => setIsBuildProjectDialogOpen(true)}
                    disabled={selectedSectionsForBuild.size === 0 || projectMutation.isPending}
                  >
                    <Building className="mr-2.5 h-4 w-4" />
                    Execute Build ({selectedSectionsForBuild.size})
                    <ChevronRight className="ml-1.5 h-3.5 w-3.5" />
                  </Button>
                </motion.div>
              ) : (
                canBuildProject && (
                  <motion.div
                    key="standard-actions"
                    initial={{ opacity: 0, y: 12 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 12 }}
                    transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                    className="w-full"
                  >
                    <Button
                      size="lg"
                      className="h-12 w-full rounded-2xl bg-primary text-[10px] font-black uppercase tracking-[0.2em] shadow-xl shadow-primary/10 transition-all hover:shadow-primary/30 group/assemble ring-1 ring-inset ring-white/10"
                      onClick={enterProjectBuildMode}
                      disabled={projectMutation.isPending}
                    >
                      <Building className="mr-2.5 h-4 w-4 transition-transform group-hover/assemble:scale-110" />
                      Assemble Project Manifest
                    </Button>
                  </motion.div>
                )
              )}
            </AnimatePresence>
          </div>
        </div>
      </SidebarContainer>
    </>
  );
}

