'use client';

import React, { useState } from 'react';
import { Trash2, Plus, StickyNote, ListChecks } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { useBuilderStore } from '@/hooks';
import { useGuidelineEditor } from '@/modules/ai-content/adapters/hooks/report-mode/use-guideline-editor';

/**
 * GuidelineEditor — Context-sensitive AI behavioral and technical constraint editor.
 * Manages the "Primary Vector" (prompt) and "Constraint Matrix" (guidelines).
 */

interface GuidelineEditorProps {
  itemId: string;
  selectedIds?: string[];
}

export function GuidelineEditor({ itemId, selectedIds }: GuidelineEditorProps) {
  const { updateProject } = useBuilderStore();
  const {
    section,
    prompt,
    setPrompt,
    guidelines,
    setGuidelines,
  } = useGuidelineEditor(itemId);

  const [newGuideline, setNewGuideline] = useState('');

  if (!section) return null;

  const handleAddGuideline = () => {
    if (!newGuideline.trim()) return;
    const g = newGuideline.trim();

    if (selectedIds && selectedIds.length > 0) {
      updateProject(p => {
        selectedIds.forEach(id => {
          p.updateSection(id, s => s.withProps({
            guidelines: [...(s.guidelines || []), g]
          }));
        });
      });
    } else {
      setGuidelines([...guidelines, g]);
    }
    setNewGuideline('');
  };

  const handleRemoveGuideline = (index: number) => {
    if (selectedIds && selectedIds.length > 0) {
      const gToRemove = guidelines[index];
      updateProject(p => {
        selectedIds.forEach(id => {
          p.updateSection(id, s => s.withProps({
            guidelines: (s.guidelines || []).filter(g => g !== gToRemove)
          }));
        });
      });
    } else {
      const updatedGuidelines = [...guidelines];
      updatedGuidelines.splice(index, 1);
      setGuidelines(updatedGuidelines);
    }
  };

  return (
    <div className="space-y-8 pt-2">
      {/* HUD Header Group */}
      <div className="space-y-1.5 px-1">
        <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-primary/70 flex items-center gap-2.5">
            <ListChecks className="h-3.5 w-3.5" />
            Neural Guidelines
        </h4>
        <p className="text-[9px] text-muted-foreground italic font-medium opacity-60 uppercase tracking-widest">
            Define architectural logic and technical constraints.
        </p>
      </div>

      <div className="space-y-8 relative px-1">
        {/* Depth accent line */}
        <div className="absolute left-[-1.25rem] top-0 bottom-0 w-px bg-gradient-to-b from-primary/30 via-primary/5 to-transparent" />

        {/* Primary Vector Zone */}
        <div className="space-y-4">
          <div className="flex items-center gap-2 group/label">
            <StickyNote className="h-3.5 w-3.5 text-primary/40 group-hover/label:text-primary transition-colors" />
            <Label htmlFor={`prompt-${itemId}`} className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60">Primary Directive</Label>
          </div>
          <div className="relative group">
            <div className="absolute -inset-1 bg-gradient-to-r from-primary/10 to-transparent rounded-2xl blur opacity-0 group-focus-within:opacity-100 transition duration-500" />
            <Textarea
                id={`prompt-${itemId}`}
                defaultValue={prompt}
                onBlur={(e) => {
                    const val = e.target.value;
                    if (selectedIds && selectedIds.length > 0) {
                        updateProject(p => {
                            selectedIds.forEach(id => {
                                p.updateSection(id, s => s.withProps({ prompt: val }));
                            });
                        });
                    } else {
                        setPrompt(val);
                    }
                }}
                rows={5}
                className="relative min-h-[140px] w-full text-[11px] bg-muted/5 border-primary/10 focus-visible:ring-primary/20 leading-relaxed resize-none p-4 rounded-2xl shadow-inner font-serif italic transition-all hover:bg-muted/8"
                placeholder="Initialize primary AI instructions for this node..."
            />
          </div>
        </div>

        <Separator className="bg-gradient-to-r from-primary/20 via-primary/5 to-transparent h-px" />

        {/* Constraint Matrix Zone */}
        <div className="space-y-5">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <Plus className="h-3.5 w-3.5 text-primary/60" />
              <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">Logic Constraints</Label>
            </div>
            <Badge variant="outline" className="h-5 text-[9px] font-black border-primary/20 bg-primary/5 text-primary tabular-nums px-2.5 rounded-full shadow-inner ring-1 ring-inset ring-primary/10">
                {guidelines.length} NODES
            </Badge>
          </div>

          <div className="space-y-4">
            <div className="flex gap-2.5 group/input">
              <Input
                value={newGuideline}
                onChange={(e) => setNewGuideline(e.target.value)}
                placeholder="Incorporate new technical rule..."
                onKeyDown={(e) => { if(e.key === 'Enter') { e.preventDefault(); handleAddGuideline(); }}}
                className="h-10 text-[11px] bg-muted/5 border-primary/10 focus-visible:ring-primary/20 transition-all rounded-xl font-medium"
              />
              <Button 
                type="button" 
                size="icon" 
                onClick={handleAddGuideline} 
                className="h-10 w-10 shrink-0 rounded-xl shadow-xl shadow-primary/10 group-hover/input:scale-105 active:scale-95 transition-all"
              >
                <Plus className="h-4 w-4" />
              </Button>
            </div>

            <ScrollArea className="h-56 w-full rounded-[24px] border border-primary/10 bg-muted/5 shadow-inner">
              <div className="p-2.5 space-y-2">
                {guidelines.length > 0 ? (
                  guidelines.map((guideline, index) => (
                    <div 
                        key={index} 
                        className="flex items-start justify-between text-[11px] p-3.5 rounded-xl border border-primary/5 bg-background/60 backdrop-blur-md gap-4 group shadow-sm hover:border-primary/20 transition-all"
                    >
                      <div className="flex items-center gap-3.5 flex-1 min-w-0">
                         <div className="h-1.5 w-1.5 rounded-full bg-primary/40 group-hover:bg-primary transition-colors shrink-0 mt-1.5 shadow-[0_0_6px_rgba(var(--primary),0.2)]" />
                         <span className="leading-relaxed text-muted-foreground group-hover:text-foreground transition-colors font-medium">{guideline}</span>
                      </div>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-destructive/10 hover:text-destructive rounded-lg"
                        onClick={() => handleRemoveGuideline(index)}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                  ))
                ) : (
                  <div className="flex flex-col items-center justify-center py-16 px-6 text-center space-y-4 opacity-30">
                    <div className="p-5 rounded-full bg-muted/20 border border-dashed border-muted-foreground/40 shadow-inner">
                        <ListChecks className="h-9 w-9 text-muted-foreground" />
                    </div>
                    <div className="space-y-1.5">
                        <p className="text-[10px] text-muted-foreground font-black uppercase tracking-[0.25em]">Manifest Stable</p>
                        <p className="text-[9px] text-muted-foreground font-medium italic">Define architectural rules to optimize AI output.</p>
                    </div>
                  </div>
                )}
              </div>
            </ScrollArea>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { SlidersHorizontal, Zap, Target, Layout, PenTool } from 'lucide-react';
import { Label } from '@/components/ui/label';
import { Slider } from '@/components/ui/slider';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group';
import { cn } from '@/infrastructure/utils/cn';
import { useBuilderStore } from '@/hooks';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { DiagramType, DiagramTypeSchema, ToneSchema } from '@/modules/ai/domain/schemas';
import { GenerationControlState } from '@/modules/ai-content/domain/entities/ControlTypes';

/**
 * ControlPanel — Low-level neural parameter tuning HUD.
 * Manages Tone, Complexity, Formality, and Output Formats for AI generation.
 */

interface ControlPanelProps {
    section: Section;
    selectedIds?: string[];
}

const diagramTypes = DiagramTypeSchema.options.map(value => ({
    value,
    label: value.charAt(0).toUpperCase() + value.slice(1).replace('-', ' ')
}));

const toneOptions = ToneSchema.options.map(tone => ({
    value: tone,
    label: tone.charAt(0).toUpperCase() + tone.slice(1)
}));

export function ControlPanel({ section, selectedIds }: ControlPanelProps) {
    const { updateProject } = useBuilderStore();

    const handleUpdate = (updates: Partial<GenerationControlState>) => {
        const targets = selectedIds && selectedIds.length > 0 ? selectedIds : [section.id];
        updateProject(p => {
            targets.forEach(id => {
                p.updateSection(id, s => s.withProps({
                    controls: { ...s.controls, ...updates }
                }));
            });
        });
    };

    const handleDetectFormats = () => {
        if (!section.content) return;
        const lines = section.content.split('\n');
        const detected: GenerationControlState['outputStyle'] = {
            paragraph: lines.some(l => l.trim() && !l.startsWith('#') && !l.startsWith('-') && !l.startsWith('|')),
            bulletPoints: lines.some(l => l.trim().startsWith('- ') || l.trim().startsWith('* ')),
            numberedList: lines.some(l => /^\d+\./.test(l.trim())),
            table: lines.some(l => l.includes('|')),
            code: lines.some(l => l.startsWith('```')),
            mermaid: lines.some(l => l.includes('mermaid')),
        };
        handleUpdate({ outputStyle: detected });
    };

    return (
        <div className="space-y-8 pt-2">
            {/* HUD Header */}
            <div className="space-y-1.5 px-1">
                <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-primary/70 flex items-center gap-2.5">
                    <SlidersHorizontal className="h-3.5 w-3.5" />
                    Cognitive Vectors
                </h4>
                <p className="text-[9px] text-muted-foreground italic font-medium opacity-60 uppercase tracking-widest">
                    Fine-tune the neural weight and linguistic elevation.
                </p>
            </div>

            <div className="space-y-8 relative px-1">
                {/* Depth accent line */}
                <div className="absolute left-[-1.25rem] top-0 bottom-0 w-px bg-gradient-to-b from-primary/30 via-primary/5 to-transparent" />

                {/* Linguistic Weight Zone */}
                <div className="space-y-6">
                    <div className="space-y-4">
                        <div className="flex justify-between items-center group/label">
                            <div className="flex items-center gap-2">
                                <PenTool className="h-3.5 w-3.5 text-primary/40 group-hover/label:text-primary transition-colors" />
                                <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60">Neural Formality</Label>
                            </div>
                            <Badge variant="outline" className="h-5 text-[9px] font-black border-primary/20 bg-primary/5 text-primary tabular-nums shadow-inner ring-1 ring-inset ring-primary/10">
                                {section.controls.formality}%
                            </Badge>
                        </div>
                        <Slider 
                            value={[section.controls.formality]} 
                            onValueChange={(v) => handleUpdate({ formality: v[0] })} 
                            min={0} max={100} step={5} 
                            className="py-2"
                        />
                    </div>

                    <div className="space-y-4">
                        <div className="flex justify-between items-center group/label">
                            <div className="flex items-center gap-2">
                                <Target className="h-3.5 w-3.5 text-primary/40 group-hover/label:text-primary transition-colors" />
                                <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60">Syntactic Density</Label>
                            </div>
                            <Badge variant="outline" className="h-5 text-[9px] font-black border-primary/20 bg-primary/5 text-primary tabular-nums shadow-inner ring-1 ring-inset ring-primary/10">
                                {section.controls.complexity}%
                            </Badge>
                        </div>
                        <Slider 
                            value={[section.controls.complexity]} 
                            onValueChange={(v) => handleUpdate({ complexity: v[0] })} 
                            min={0} max={100} step={5} 
                            className="py-2"
                        />
                    </div>
                </div>

                <div className="h-px bg-primary/5" />

                {/* Persona & Flow Zone */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-3">
                        <Label className="text-[9px] font-black uppercase tracking-widest text-muted-foreground/60">Intelligence Tone</Label>
                        <Select 
                            value={section.controls.tone} 
                            onValueChange={(v) => handleUpdate({ tone: v as any })}
                        >
                            <SelectTrigger className="h-10 text-[11px] font-bold bg-muted/5 border-primary/10 rounded-xl focus:ring-primary/20 transition-all">
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent className="rounded-2xl border-primary/10 shadow-2xl backdrop-blur-3xl">
                                {toneOptions.map(opt => (
                                    <SelectItem key={opt.value} value={opt.value} className="text-[11px] font-medium py-2.5 focus:bg-primary/5 focus:text-primary">
                                        {opt.label}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="space-y-3">
                        <Label className="text-[9px] font-black uppercase tracking-widest text-muted-foreground/60">Diagram Logic</Label>
                        <Select 
                            value={section.controls.diagramType} 
                            onValueChange={(v) => handleUpdate({ diagramType: v as DiagramType })}
                        >
                            <SelectTrigger className="h-10 text-[11px] font-bold bg-muted/5 border-primary/10 rounded-xl focus:ring-primary/20 transition-all">
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent className="rounded-2xl border-primary/10 shadow-2xl backdrop-blur-3xl">
                                {diagramTypes.map(opt => (
                                    <SelectItem key={opt.value} value={opt.value} className="text-[11px] font-medium py-2.5 focus:bg-primary/5 focus:text-primary">
                                        {opt.label}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>
                </div>

                {/* Output Style HUD */}
                <div className="space-y-4 pt-2">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2.5">
                            <Layout className="h-3.5 w-3.5 text-primary/60" />
                            <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">Structural Matrix</Label>
                        </div>
                        <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={handleDetectFormats}
                            disabled={!section.content}
                            className="h-7 px-3 rounded-lg text-[9px] font-black uppercase tracking-widest border border-primary/10 hover:bg-primary/5 hover:text-primary transition-all gap-1.5"
                        >
                            <Zap className="h-3 w-3" />
                            Auto-Sync
                        </Button>
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                        {Object.entries(section.controls.outputStyle).map(([key, enabled]) => (
                            <button
                                key={key}
                                onClick={() => handleUpdate({ 
                                    outputStyle: { ...section.controls.outputStyle, [key]: !enabled } 
                                })}
                                className={cn(
                                    "flex items-center justify-between px-3 py-2.5 rounded-xl border transition-all duration-300 group/btn",
                                    enabled 
                                        ? "bg-primary/10 border-primary/20 text-primary shadow-sm" 
                                        : "bg-muted/5 border-transparent text-muted-foreground hover:border-primary/10 hover:bg-muted/10"
                                )}
                            >
                                <span className="text-[10px] font-bold uppercase tracking-wider">
                                    {key.replace(/([A-Z])/g, ' $1').trim()}
                                </span>
                                <div className={cn(
                                    "h-1.5 w-1.5 rounded-full transition-all duration-500",
                                    enabled ? "bg-primary shadow-[0_0_8px_rgba(var(--primary),0.6)]" : "bg-muted-foreground/20 group-hover/btn:bg-primary/40"
                                )} />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useMemo } from 'react';
